window.editStudent=async function(e,t){try{const n=e.closest(".student-card"),a=n.querySelector(".edit-name").value,l=n.querySelector(".edit-age").value,s=n.querySelector(".edit-course").value,d=n.querySelector(".edit-skills").value,o=n.querySelector(".edit-email").value,c=n.querySelector(".edit-enrolled").value;await fetch("./database.json",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:t,name:a,age:l,course:s,skills:d,email:o,isEnrolled:c})}),alert("Дані оновлено!")}catch(e){console.log(e)}},window.deleteStudent=async function(e){try{const t=e.closest(".student-card");await fetch("./database.json",{method:"DELETE"}),t.remove()}catch(e){console.log(e)}},document.getElementById("get-students-btn").addEventListener("click",async()=>{const e=await async function(){try{const e=await fetch("./database.json");return(await e.json()).students||[]}catch(e){return console.error("Помилка завантаження даних:",e),[]}}();document.getElementById("students-container").innerHTML=function(e){return e.map(e=>`\n      <div class="student-card">\n        <input class="edit-name" value="${e.name}">\n        <p>ID: <b>${e.id}</b></p>\n        <p>Вік: <input class="edit-age" value="${e.age}"></p>\n        <p>Курс: <input class="edit-course" value="${e.course}"></p>\n        <p>Навички: <input class="edit-skills" value="${e.skills}"></p>\n        <p>Email: <input class="edit-email" value="${e.email}"></p>\n        <p>Статус: <input class="edit-enrolled" value="${e.isEnrolled}"></p>\n\n        <div class="action-btns">\n          <button onclick="editStudent(this, '${e.id}')">Редагувати</button>\n          <button class="delete-btn" onclick="deleteStudent(this)">Видалити</button>\n        </div>\n      </div>\n    `).join("")}(e)}),document.getElementById("add-student-form").addEventListener("submit",async e=>{e.preventDefault();const t={id:Date.now(),name:document.getElementById("name").value,age:Number(document.getElementById("age").value),course:document.getElementById("course").value,skills:document.getElementById("skills").value,email:document.getElementById("email").value,isEnrolled:document.getElementById("isEnrolled").checked};try{await fetch("./database.json",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)}),document.getElementById("add-student-form").reset(),alert("Студента успішно додано!")}catch(e){console.log("Помилка при додаванні:",e)}});